from PIL import Image
import numpy as np
from collections import deque
for n in [38,40]:
 for cam in ['robot0_agentview_right','robot0_agentview_left','robot0_eye_in_hand']:
  a=np.array(Image.open(f'/app/output/records/call_{n:03d}/last/{cam}.jpg'))
  r,g,b=a[:,:,0],a[:,:,1],a[:,:,2]
  mask=(r>105)&(g>48)&(g<170)&(b<125)&(r>g*1.20)&(g>b*1.08)
  # connected components 8-connected
  H,W=mask.shape; seen=np.zeros_like(mask); comps=[]
  for y,x in zip(*np.where(mask)):
   if seen[y,x]:continue
   q=[(y,x)];seen[y,x]=1;pts=[]
   while q:
    yy,xx=q.pop();pts.append((yy,xx))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      ny,nx=yy+dy,xx+dx
      if 0<=ny<H and 0<=nx<W and mask[ny,nx] and not seen[ny,nx]:seen[ny,nx]=1;q.append((ny,nx))
   if len(pts)>12:
    ys=[p[0] for p in pts];xs=[p[1] for p in pts];comps.append((len(pts),(min(xs),min(ys),max(xs),max(ys)),(sum(xs)/len(xs),sum(ys)/len(ys))))
  print(n,cam,sorted(comps,reverse=True)[:6])
